def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by their digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = str(n)
        total = 0

        # Every number containing a zero has digit product zero, so it is
        # beautiful. Count these separately; the digit DP below uses digits
        # 1 through 9 only.
        for length in range(1, len(digits) + 1):
            all_numbers = 9 * (10 ** (length - 1))
            no_zero_numbers = 9 ** length
            if length < len(digits):
                total += all_numbers - no_zero_numbers
            else:
                bound = int(digits)
                total += bound - (bound // 10 ** (length - 1)) * 10 ** (length - 1)
                # The expression above is not the desired count with a zero
                # digit; count zero-containing values by digit DP below.
                total -= bound - (bound // 10 ** (length - 1)) * 10 ** (length - 1)

        # Count numbers containing zero up to n with a small standard digit DP.
        # Leading zeroes are ignored; a zero after the first digit marks a hit.
        zero_dp = {(True, False): 1}
        for ch in digits:
            cap = int(ch)
            next_dp = {}
            for (tight, has_zero), count in zero_dp.items():
                limit = cap if tight else 9
                for d in range(limit + 1):
                    key = (tight and d == cap, has_zero or d == 0)
                    next_dp[key] = next_dp.get(key, 0) + count
            zero_dp = next_dp
        total += zero_dp.get((False, True), 0) + zero_dp.get((True, True), 0)

        # Count beautiful numbers with no zero digits, by fixing their digit
        # sum and tracking the product modulo that sum.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else "9" * length
            for target_sum in range(length, 9 * length + 1):
                modulus = target_sum
                states = {(0, 1 % modulus, True): 1}
                for pos, ch in enumerate(bound):
                    cap = int(ch)
                    following = {}
                    for (digit_sum, product_mod, tight), count in states.items():
                        limit = cap if tight else 9
                        first = 1 if pos == 0 else 1
                        for digit in range(first, limit + 1):
                            new_sum = digit_sum + digit
                            if new_sum > target_sum:
                                continue
                            new_tight = tight and digit == cap
                            key = (new_sum, (product_mod * digit) % modulus, new_tight)
                            following[key] = following.get(key, 0) + count
                    states = following
                total += sum(count for (digit_sum, product_mod, _), count in states.items()
                             if digit_sum == target_sum and product_mod == 0)
        return total

    return count_up_to(r) - count_up_to(l - 1)

def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a^b for a >= 1 and b >= 2."""
    if n < 1:
        return 0

    # If x > 1 is a perfect power, at least one prime exponent p makes x
    # a pth power. Inclusion-exclusion over those prime exponents counts the
    # union, with intersections corresponding to products of distinct primes.
    max_exponent = n.bit_length() - 1  # floor(log2(n))
