from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the winner with optimal play under the stated card rules."""
    visiting = set()

    @lru_cache(None)
    def winning(hand_t: Tuple[int, ...], hand_a: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        state = (hand_t, hand_a, table, turn)
        if not (hand_t if turn == 0 else hand_a):
            return False
        if state in visiting:
            return False
        visiting.add(state)
        hand = hand_t if turn == 0 else hand_a
        can_win = False
        for i, card in enumerate(hand):
            remaining = hand[:i] + hand[i + 1:]
            new_table = tuple(sorted(table + (card,)))
            if turn == 0:
                nh_t, nh_a = remaining, hand_a
            else:
                nh_t, nh_a = hand_t, remaining
            if not winning(nh_t, nh_a, new_table, 1 - turn):
                can_win = True
                break
            for j, table_card in enumerate(table):
                if table_card <= card:
                    exchanged = tuple(sorted(remaining + (table_card,)))
                    nt = tuple(sorted(table[:j] + table[j + 1:] + (card,)))
                    if turn == 0:
                        nh_t, nh_a = exchanged, hand_a
                    else:
                        nh_t, nh_a = hand_t, exchanged
                    if not winning(nh_t, nh_a, nt, 1 - turn):
                        can_win = True
                        break
            if can_win:
                break
        visiting.remove(state)
        return can_win

    t = tuple(sorted(takahashi_cards[:n]))
    a = tuple(sorted(aoki_cards[:m]))
    table = tuple(sorted(table_cards[:l]))
    return "Takahashi" if winning(t, a, table, 0) else "Aoki"

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given section lengths, minimize the cost of sensors whose combined coverage meets each length."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    states = {(0, 0): 0}
    for length in sections[:n]:
        # For each possible number of type 1 sensors, use the fewest type 2
        # sensors that complete coverage of this section.
        options = []
        max1 = min(k1, (length + l1 - 1) // l1)
        for count1 in range(max1 + 1):
            remainder = length - count1 * l1
            count2 = max(0, (remainder + l2 - 1) // l2)
            if count2 <= k2:
                options.append((count1, count2, count1 * c1 + count2 * c2))

        next_states = {}
        for (used1, used2), cost in states.items():
            for add1, add2, add_cost in options:
                total1, total2 = used1 + add1, used2 + add2
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + add_cost
                    if value < next_states.get(key, float("inf")):
                        next_states[key] = value

        # Keep only nondominated allocations; fewer sensors and lower cost
        # can never make a later section harder to cover.
        ordered = sorted((a, b, cost) for (a, b), cost in next_states.items())
        frontier = []
        for a, b, cost in ordered:
            if any(pa <= a and pb <= b and pc <= cost for pa, pb, pc in frontier):
                continue
            frontier = [(pa, pb, pc) for pa, pb, pc in frontier
                        if not (a <= pa and b <= pb and cost <= pc)]
            frontier.append((a, b, cost))
        states = {(a, b): cost for a, b, cost in frontier}
        if not states:
            return -1

    return min(states.values(), default=-1)

def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by their digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = str(n)
        total = 0

        # Numbers with a zero digit have product zero and are always beautiful.
        # Count them by length, requiring a nonzero leading digit.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else "9" * length
            states = {(True, False): 1}
            for pos, ch in enumerate(bound):
                cap = int(ch)
                following = {}
                for (tight, has_zero), count in states.items():
                    limit = cap if tight else 9
                    for digit in range(1 if pos == 0 else 0, limit + 1):
                        key = (tight and digit == cap, has_zero or digit == 0)
                        following[key] = following.get(key, 0) + count
                states = following
            total += sum(count for (_, has_zero), count in states.items() if has_zero)

        # For numbers without zero, fix the digit sum and track the product
        # modulo that sum. A product is divisible by the sum exactly at residue 0.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else "9" * length
            for target_sum in range(length, 9 * length + 1):
                modulus = target_sum
                states = {(0, 1 % modulus, True): 1}
                for pos, ch in enumerate(bound):
                    cap = int(ch)
                    following = {}
                    for (digit_sum, product_mod, tight), count in states.items():
                        limit = cap if tight else 9
                        for digit in range(1, limit + 1):
                            new_sum = digit_sum + digit
                            if new_sum > target_sum:
                                continue
                            new_tight = tight and digit == cap
                            key = (new_sum, (product_mod * digit) % modulus, new_tight)
                            following[key] = following.get(key, 0) + count
                    states = following
                total += sum(count for (digit_sum, product_mod, _), count in states.items()
                             if digit_sum == target_sum and product_mod == 0)
        return total

    return count_up_to(r) - count_up_to(l - 1)

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Given a string s and an integer k, partition s into k substrings such that
    the sum of the number of letter changes required to turn each substring into
    a semi-palindrome is minimized.

    A semi-palindrome has length at least 2 and some proper positive divisor d
    of its length such that every sequence of positions with the same index
    modulo d is a palindrome.
    """
    n = len(s)

    # cost[i][j] is the minimum number of edits for s[i:j] (half-open).
    cost = [[0] * (n + 1) for _ in range(n)]
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            best = length
            for d in range(1, length):
                if length % d:
                    continue
                edits = 0
                width = length // d
                # The d residue classes are independent palindromes.
                for residue in range(d):
                    for offset in range(width // 2):
                        left = start + residue + offset * d
                        right = start + residue + (width - 1 - offset) * d
                        if s[left] != s[right]:
                            edits += 1
                if edits < best:
                    best = edits
            cost[start][start + length] = best

    # dp[p][end] = minimum cost to cover s[:end] with p valid pieces.
    inf = n + 1
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for pieces in range(1, k + 1):
        # Each piece has length at least two, as required by the definition.
        min_end = 2 * pieces
        for end in range(min_end, n + 1):
            latest_start = end - 2
            earliest_start = 2 * (pieces - 1)
            for start in range(earliest_start, latest_start + 1):
                prev = dp[pieces - 1][start]
                if prev < inf:
                    candidate = prev + cost[start][end]
                    if candidate < dp[pieces][end]:
                        dp[pieces][end] = candidate
    return dp[k][n]

