from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the H×W grid can be tiled by a subset of the rectangles.

    Tiles may be rotated, must fit inside the grid, and must cover every cell
    exactly once.
    """
    tiles = tiles[:n]
    n = len(tiles)
    target_area = h * w
    areas = [a * b for a, b in tiles]
    # Subset sums let the search reject states whose remaining area cannot be
    # made from the unused tiles.
    subset_areas = [set() for _ in range(1 << n)]
    subset_areas[0].add(0)
    for used in range(1 << n):
        for i, area in enumerate(areas):
            if not (used >> i) & 1:
                subset_areas[used | (1 << i)].update(
                    amount + area for amount in subset_areas[used]
                )

    full = (1 << target_area) - 1
    placement_cache = {}

    def placement_mask(row: int, col: int, height: int, width: int) -> int:
        key = (row, col, height, width)
        mask = placement_cache.get(key)
        if mask is None:
            mask = 0
            for rr in range(row, row + height):
                start = rr * w + col
                mask |= ((1 << width) - 1) << start
            placement_cache[key] = mask
        return mask

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining_area = target_area - occupied.bit_count()
        if remaining_area not in subset_areas[((1 << n) - 1) ^ used]:
            return False

        # Fill the first uncovered cell in row-major order. Any rectangle
        # covering it must start there, since every earlier cell is occupied.
        missing = full ^ occupied
        bit = missing & -missing
        index = bit.bit_length() - 1
        row, col = divmod(index, w)

        tried_shapes = set()
        for i, (a, b) in enumerate(tiles):
            if (used >> i) & 1:
                continue
            shape = tuple(sorted((a, b)))
            if shape in tried_shapes:
                continue
            tried_shapes.add(shape)

            orientations = {(a, b), (b, a)}
            for height, width in orientations:
                if row + height > h or col + width > w:
                    continue
                mask = placement_mask(row, col, height, width)
                if occupied & mask:
                    continue
                if search(occupied | mask, used | (1 << i)):
                    return True
        return False

    return search(0, 0)

