def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Return twice the black area in the specified periodic wallpaper."""
    def local(x1, y1, x2, y2):
        if x1 == x2 or y1 == y2:
            return 0.0
        xs = {x1, x2}
        for n in range(-4, 9):
            if x1 < n < x2:
                xs.add(float(n))
        for k in range(-4, 9):
            for yy in (y1, y2):
                xx = 2*k - yy
                if x1 < xx < x2:
                    xs.add(float(xx))
        xs = sorted(xs)
        area = 0.0
        for xl, xr in zip(xs, xs[1:]):
            xm = (xl+xr)/2
            lines = [(0.0, y1), (0.0, y2)]
            for n in range(-4, 9):
                yy = 2*n
                if y1 < yy < y2:
                    lines.append((0.0, yy))
            for n in range(-4, 9):
                if y1 < 2*n-xm < y2:
                    lines.append((-1.0, 2.0*n))
            lines.sort(key=lambda z: z[0]*xm+z[1])
            for (m1,b1),(m2,b2) in zip(lines, lines[1:]):
                ym = ((m1+m2)/2)*xm+(b1+b2)/2
                if not (y1 < ym < y2):
                    continue
                black = (int(xm//1) + int(ym//2) + int((xm+ym)//2)) % 2 == 0
                if black:
                    area += ((m2-m1)*(xl+xr)/2 + (b2-b1))*(xr-xl)
        return area

    def pref(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        total = local(0, 0, 4, 4)
        return qx*qy*total + qx*local(0, 0, 4, ry) + qy*local(0, 0, rx, 4) + local(0, 0, rx, ry)

    return round(2*(pref(C,D)-pref(A,D)-pref(C,B)+pref(A,B)))

