def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves, with every empty cell as a possible start."""
    if K < 0 or K >= H * W:
        return 0

    n = H * W
    open_cells = [grid[r][c] == "." for r in range(H) for c in range(W)]
    neighbors = [[] for _ in range(n)]
    for r in range(H):
        for c in range(W):
            i = r * W + c
            if not open_cells[i]:
                continue
            if r:
                j = i - W
                if open_cells[j]:
                    neighbors[i].append(j)
            if r + 1 < H:
                j = i + W
                if open_cells[j]:
                    neighbors[i].append(j)
            if c:
                j = i - 1
                if open_cells[j]:
                    neighbors[i].append(j)
            if c + 1 < W:
                j = i + 1
                if open_cells[j]:
                    neighbors[i].append(j)

    total = 0

    def visit(cell: int, remaining: int, used: int) -> None:
        nonlocal total
        if remaining == 0:
            total += 1
            return
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not used & bit:
                visit(nxt, remaining - 1, used | bit)

    for start in range(n):
        if open_cells[start]:
            visit(start, K, 1 << start)
    return total

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    Cells that can vary among matrices with the same margins are the cells
    lying in alternating cycles. The alternating-cycle components are
    bipartite strongly connected components; a nontrivial component has at
    least two rows and two columns. If its dimensions are r by c, it
    contributes r*c variable cells. All cells between components are fixed.
    """
    if k < 0 or k > n * n:
        return False
    variable = n * n - k
    # Packable variable area is a sum of r*c rectangles with r,c >= 2.
    # Row and column dimensions are each disjoint, so their total usage
    # cannot exceed n.
    reachable = [[False] * (n + 1) for _ in range(n + 1)]
    reachable[0][0] = True
    for r_used in range(n + 1):
        for c_used in range(n + 1):
            if not reachable[r_used][c_used]:
                continue
            for r in range(2, n - r_used + 1):
                for c in range(2, n - c_used + 1):
                    # The DP needs the variable area too; use state sets below.
                    pass
    states = {(0, 0, 0)}
    for r_used in range(n + 1):
        for c_used in range(n + 1):
            current = [area for rr, cc, area in states if rr == r_used and cc == c_used]
            for area in current:
                for r in range(2, n - r_used + 1):
                    for c in range(2, n - c_used + 1):
                        new_area = area + r * c
                        if new_area <= variable:
                            states.add((r_used + r, c_used + c, new_area))
    return any(area == variable for _, _, area in states)

