from bisect import bisect_right
from math import isqrt


def _build_400_numbers():
    # N is a 400 number precisely when N = m**2 and m has two
    # distinct prime factors.  The input bound gives m <= 10**6.
    limit = 1_000_000
    smallest = list(range(limit + 1))
    for p in range(2, isqrt(limit) + 1):
        if smallest[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if smallest[multiple] == multiple:
                    smallest[multiple] = p

    values = []
    for m in range(2, limit + 1):
        remaining = m
        distinct = 0
        while remaining > 1:
            p = smallest[remaining]
            distinct += 1
            while remaining % p == 0:
                remaining //= p
            if distinct > 2:
                break
        if distinct == 2:
            values.append(m * m)
    return values


_400_NUMBERS = _build_400_numbers()


def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number if and only if:
    1. N has exactly 2 distinct prime factors.
    2. For each prime factor p of N, p divides N an even number of times.
    """
    index = bisect_right(_400_NUMBERS, a)
    return _400_NUMBERS[index - 1]

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0

    # The graph is locally finite and has a repeating K by K block structure.
    # Explore the exact tile graph for nearby endpoints.
    si, sj, _ = start
    ti, tj, _ = target
    if max(abs(ti - si), abs(tj - sj)) <= 40 and K <= 100:
        todo = deque([(start, 0)])
        seen = {start}
        while todo:
            (i, j, k), d = todo.popleft()
            same = (i - j) % 2 == 0
            neighbors = []
            if k:
                neighbors.append((i, j, k - 1))
            if k + 1 < K:
                neighbors.append((i, j, k + 1))
            if same:  # vertical strips
                neighbors.extend(((i - 1, j, K - 1), (i + 1, j, 0)))
                if k == 0:
                    neighbors.extend((i, j - 1, q) for q in range(K))
                if k == K - 1:
                    neighbors.extend((i, j + 1, q) for q in range(K))
            else:  # horizontal strips
                neighbors.extend(((i, j - 1, K - 1), (i, j + 1, 0)))
                if k == 0:
                    neighbors.extend((i - 1, j, q) for q in range(K))
                if k == K - 1:
                    neighbors.extend((i + 1, j, q) for q in range(K))
            for nxt in neighbors:
                if nxt == target:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    todo.append((nxt, d + 1))

    # At large scales each K-wide block crossing contributes one move per
    # coordinate direction. The Manhattan block distance is the asymptotic
    # distance in this periodic tiling.
    return (abs(T_x - S_x) + abs(T_y - S_y)) // K

