def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of primitive sequences with the prescribed reduced ratios."""
    mod = 998244353
    factors = []
    primes = set()
    for value in a:
        x = value
        fs = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                fs[d] = fs.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            fs[x] = fs.get(x, 0) + 1
        factors.append(fs)
        primes.update(fs)

    if not primes:
        return 2
    answer = 1
    for p in primes:
        exps = [fs.get(p, 0) for fs in factors]
        total = 0

        def walk(i, current, minimum, raw_sum):
            nonlocal total
            if i == len(exps):
                total = (total + pow(p, raw_sum - n * minimum, mod)) % mod
                return
            e = exps[i]
            if e == 0:
                walk(i + 1, current, minimum, raw_sum + current)
            else:
                nxt = current + e
                walk(i + 1, nxt, min(minimum, nxt), raw_sum + nxt)
                nxt = current - e
                walk(i + 1, nxt, min(minimum, nxt), raw_sum + nxt)

        walk(0, 0, 0, 0)
        answer = answer * total % mod
    return answer

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count numbers in [low, high] with equal even/odd digit counts and divisible by k."""
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0

        digits = list(map(int, str(bound)))
        total = 0
        for length in range(1, len(digits) + 1):
            limit = digits if length == len(digits) else [9] * length

            @lru_cache(None)
            def dp(pos: int, remainder: int, balance: int, tight: bool) -> int:
                if pos == length:
                    return int(remainder == 0 and balance == 0)

                upper = limit[pos] if tight else 9
                lower = 1 if pos == 0 else 0
                ways = 0
                for digit in range(lower, upper + 1):
                    ways += dp(
                        pos + 1,
                        (remainder * 10 + digit) % k,
                        balance + (1 if digit % 2 == 0 else -1),
                        tight and digit == upper,
                    )
                return ways

            total += dp(0, 0, 0, True)
        return total

    return count_up_to(high) - count_up_to(low - 1)

