from typing import List

MOD = 998244353
ROOT = 3


def _ntt(a: list[int], invert: bool) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of lengths 1 through K respecting letter caps."""
    if not any(C):
        return 0
    if all(c >= K for c in C):
        return (pow(26, K + 1, MOD) - 26) * pow(25, MOD - 2, MOD) % MOD

    # Work with exponential generating functions: the coefficient of x^n
    # in the product is the number of valid length-n strings divided by n!.
    fact = [1] * (K + 1)
    invfact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[K] = pow(fact[K], MOD - 2, MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    size = 1
    while size < 2 * K + 1:
        size <<= 1
    coeff = [0] * size
    coeff[0] = 1

    for cap in C:
        if cap <= 0:
            continue
        poly = [0] * size
        for j in range(min(cap, K) + 1):
            poly[j] = invfact[j]
        _ntt(coeff, False)
        _ntt(poly, False)
        for i in range(size):
            coeff[i] = coeff[i] * poly[i] % MOD
        _ntt(coeff, True)
        for i in range(K + 1, size):
            coeff[i] = 0

    return sum(coeff[n] * fact[n] for n in range(1, K + 1)) % MOD

import heapq


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    sx, sy, sp = locate(S_x, S_y)
    tx, ty, tp = locate(T_x, T_y)
    if (sx, sy) == (tx, ty):
        return abs(sp - tp)

    # For very distant blocks, alternating horizontal and vertical progress
    # attains the Manhattan lower bound; endpoint adjustments are local.
    span = abs(tx - sx) + abs(ty - sy)
    if span > 80:
        return span

    # Each block is a path of K tiles. Only positions at its ends, or the
    # start/target positions, can be useful when crossing block boundaries.
    pad = 2
    x0, x1 = min(sx, tx) - pad, max(sx, tx) + pad
    y0, y1 = min(sy, ty) - pad, max(sy, ty) + pad
    n = K - 1

    def positions(i, j):
        vals = {0, n}
        if (i, j) == (sx, sy):
            vals.add(sp)
        if (i, j) == (tx, ty):
            vals.add(tp)
        return sorted(vals)

    # State is a tile represented by its block and its strip index.
    nodes = {}
    for i in range(x0, x1 + 1):
        for j in range(y0, y1 + 1):
            for p in positions(i, j):
                nodes[(i, j, p)] = []

    for i in range(x0, x1 + 1):
        for j in range(y0, y1 + 1):
            ps = positions(i, j)
            for a in ps:
                for b in ps:
                    if a != b:
                        nodes[(i, j, a)].append(((i, j, b), abs(a - b)))

            same = (i + j) % 2 == 0  # horizontal-strip block
            # Connect to the block on the right.
            if i < x1:
                if same:
                    # H tiles all meet the westmost vertical tile.
                    q = 0
                    for p in ps:
                        nodes[(i, j, p)].append(((i + 1, j, q), 1))
                        nodes[(i + 1, j, q)].append(((i, j, p), 1))
                else:
                    # The eastmost vertical tile meets every H tile.
                    q = n
                    for p in positions(i + 1, j):
                        nodes[(i, j, q)].append(((i + 1, j, p), 1))
                        nodes[(i + 1, j, p)].append(((i, j, q), 1))
            # Connect to the block above.
            if j < y1:
                if same:
                    # The top H tile meets every vertical tile.
                    q = n
                    for p in positions(i, j + 1):
                        nodes[(i, j, q)].append(((i, j + 1, p), 1))
                        nodes[(i, j + 1, p)].append(((i, j, q), 1))
                else:
                    # Every vertical tile meets the bottom H tile.
                    q = 0
                    for p in ps:
                        nodes[(i, j, p)].append(((i, j + 1, q), 1))
                        nodes[(i, j + 1, q)].append(((i, j, p), 1))

    start, goal = (sx, sy, sp), (tx, ty, tp)
    dist = {start: 0}
    queue = [(0, start)]
    while queue:
        d, node = heapq.heappop(queue)
        if d != dist[node]:
            continue
        if node == goal:
            return d
        for nxt, cost in nodes[node]:
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heapq.heappush(queue, (nd, nxt))
    return span

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count ordered length-M sequences whose product is at most N and has
    divisor sum divisible by 3, modulo 998244353.

    The number of sequences with a fixed product n is the M-fold divisor
    function: for n = product(p**e), it is product(binomial(M+e-1, e)).
    """
    if N < 1 or M < 1:
        return 0

    # A segmented factorization keeps memory bounded while allowing each
    # integer's prime exponents and divisor-sum residue to be computed.
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0: min(2, limit + 1)] = b"\x00" * min(2, limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p : limit + 1 : p] = b"\x00" * (((limit - p * p) // p) + 1)

    max_exp = N.bit_length()
    ways = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        ways[e] = ways[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    block_size = 1 << 17
    answer = 0
    for low in range(1, N + 1, block_size):
        high = min(N, low + block_size - 1)
        size = high - low + 1
        rem = list(range(low, high + 1))
        weight = [1] * size
        good = bytearray(size)

        for p in primes:
            if p * p > high:
                break
            first = ((low + p - 1) // p) * p
            for value in range(first, high + 1, p):
                idx = value - low
                exponent = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    exponent += 1
                if exponent:
                    weight[idx] = weight[idx] * ways[exponent] % MOD
                    if p % 3 == 2:
                        if exponent & 1:
                            good[idx] = 1
                    elif (exponent + 1) % 3 == 0:
                        good[idx] = 1

        for i, leftover in enumerate(rem):
            if leftover > 1:
                weight[i] = weight[i] * M % MOD
                if leftover % 3 == 2:
                    good[i] = 1

        # 1 has divisor sum 1, and is not good.
        for i in range(size):
            if good[i]:
                answer += weight[i]
        answer %= MOD

    return answer

