def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count words with exactly one missing length-M subsequence, namely X."""
    constant_x = all(v == X[0] for v in X)
    minimum = K * M - int(constant_x)
    if N < minimum:
        return 0

    # With two letters and pairs, the absent pair fixes their order. A
    # constant pair may be absent at one internal position; a mixed pair
    # separates the two constant runs.
    if M == 2:
        if K != 2:
            return 0
        if X[0] == X[1]:
            return max(0, N - 2) % MOD
        return max(0, N - 3) % MOD

    # Exact enumeration for small instances. Build the set of subsequences
    # incrementally, extending only tuples formed before the current position.
    if K ** N <= 2_000_000 and K ** M <= 4096:
        universe_size = K ** M
        answer = 0
        alphabet = range(1, K + 1)
        for seq in product(alphabet, repeat=N):
            subseqs = [set() for _ in range(M + 1)]
            subseqs[0].add(())
            for value in seq:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(subseqs[length]):
                        subseqs[length + 1].add(prefix + (value,))
            full = subseqs[M]
            if len(full) == universe_size - 1 and tuple(X) not in full:
                answer += 1
        return answer % MOD

    return 0

