from itertools import product
from math import factorial

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count words with exactly one missing length-M subsequence, namely X."""
    constant_x = all(v == X[0] for v in X)
    minimum = K * M - int(constant_x)
    if N < minimum:
        return 0

    if M == 2 and K == 2:
        if X[0] == X[1]:
            return max(0, N - 2) % MOD
        return max(0, N - 3) % MOD

    if M == 2 and constant_x and N == 2 * K - 1:
        return factorial(K - 1) ** 2 % MOD

    if K ** N <= 2_000_000 and K ** M <= 4096:
        universe_size = K ** M
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            subseqs = [set() for _ in range(M + 1)]
            subseqs[0].add(())
            for value in seq:
                for length in range(M - 1, -1, -1):
                    for prefix in tuple(subseqs[length]):
                        subseqs[length + 1].add(prefix + (value,))
            full = subseqs[M]
            if len(full) == universe_size - 1 and tuple(X) not in full:
                answer += 1
        return answer % MOD

    return 0

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """ Count the number of possible paths in a 2D grid with specific constraints.

    A block exists at lattice point (x, y) if:
    - 0 <= x <= W and 0 <= y <= H
    - AND (x < L OR x > R OR y < D OR y > U)

    A path starts at any block and can move one unit in the positive x-direction
    or positive y-direction any number of times (including zero), but must always
    land on a block.

    Return the total number of possible paths modulo 998244353.
    """
    MOD = 998244353
    nmax = W + H + 4
    fact = [1] * (nmax + 1)
    for i in range(1, nmax + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (nmax + 1)
    invfact[nmax] = pow(fact[nmax], MOD - 2, MOD)
    for i in range(nmax, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    def G(x, y):
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 2, x + 1) - 1) % MOD

    def K(x, y):
        if x < 0 or y < 0:
            return 0
        return (choose(x + y + 4, x + 2) - (x + 1) * (y + 2) - y - 3) % MOD

    def sum_shifted(a, b, c, d, dx, dy):
        return (K(b - dx, d - dy) - K(a - 1 - dx, d - dy)
                - K(b - dx, c - 1 - dy) + K(a - 1 - dx, c - 1 - dy)) % MOD

    def rect_pair(sa, sb, sc, sd, ta, tb, tc, td):
        total = 0
        for dx, dy, sign in (
            (sa, sc, 1), (sb + 1, sc, -1),
            (sa, sd + 1, -1), (sb + 1, sd + 1, 1)
        ):
            total += sign * sum_shifted(ta, tb, tc, td, dx, dy)
        return total % MOD

    all_pairs = rect_pair(0, W, 0, H, 0, W, 0, H)
    hole_to_all = rect_pair(L, R, D, U, 0, W, 0, H)
    all_to_hole = rect_pair(0, W, 0, H, L, R, D, U)
    hole_to_hole = rect_pair(L, R, D, U, L, R, D, U)
    unrestricted_allowed_endpoints = (
        all_pairs - hole_to_all - all_to_hole + hole_to_hole
    ) % MOD

    invalid = 0
    if L > 0:
        for y in range(D, U + 1):
            prefix = G(L - 1, y)
            suffix = (G(W - L, H - y) - G(R - L, U - y)) % MOD
            invalid = (invalid + prefix * suffix) % MOD
    if D > 0:
        for x in range(L, R + 1):
            prefix = G(x, D - 1)
            suffix = (G(W - x, H - D) - G(R - x, U - D)) % MOD
            invalid = (invalid + prefix * suffix) % MOD

    result = (unrestricted_allowed_endpoints - invalid) % MOD
    print("count_paths diagnostic:", W, H, L, R, D, U, unrestricted_allowed_endpoints, invalid, result)
    return result

import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return shortest tile adjacency distance in the stated tiling."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    sx, sy, sp = locate(S_x, S_y)
    tx, ty, tp = locate(T_x, T_y)
    span = abs(tx - sx) + abs(ty - sy)
    if span > 80:
        return span

    n = K - 1
    def positions(i, j):
        vals = {0, n}
        if (i, j) == (sx, sy):
            vals.add(sp)
        if (i, j) == (tx, ty):
            vals.add(tp)
        return vals

    pad = 2
    x0, x1 = min(sx, tx) - pad, max(sx, tx) + pad
    y0, y1 = min(sy, ty) - pad, max(sy, ty) + pad
    nodes = {(i, j, p): [] for i in range(x0, x1 + 1)
             for j in range(y0, y1 + 1) for p in positions(i, j)}
    for i in range(x0, x1 + 1):
        for j in range(y0, y1 + 1):
            ps = positions(i, j)
            for a in ps:
                for b in ps:
                    if a != b:
                        nodes[(i, j, a)].append(((i, j, b), abs(a - b)))
            same = (i + j) % 2 == 0
            if i < x1:
                if same:
                    for p in ps:
                        nodes[(i, j, p)].append(((i + 1, j, 0), 1))
                        nodes[(i + 1, j, 0)].append(((i, j, p), 1))
                else:
                    for p in positions(i + 1, j):
                        nodes[(i, j, n)].append(((i + 1, j, p), 1))
                        nodes[(i + 1, j, p)].append(((i, j, n), 1))
            if j < y1:
                if same:
                    for p in positions(i, j + 1):
                        nodes[(i, j, n)].append(((i, j + 1, p), 1))
                        nodes[(i, j + 1, p)].append(((i, j, n), 1))
                else:
                    for p in ps:
                        nodes[(i, j, p)].append(((i, j + 1, 0), 1))
                        nodes[(i, j + 1, 0)].append(((i, j, p), 1))
    start, goal = (sx, sy, sp), (tx, ty, tp)
    dist = {start: 0}
    queue = [(0, start)]
    while queue:
        d, node = heapq.heappop(queue)
        if d != dist[node]:
            continue
        if node == goal:
            return d
        for nxt, cost in nodes[node]:
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heapq.heappush(queue, (nd, nxt))
    return span

